{
  "name": "env_get",
  "confidence": "low",
  "docstring": "Pops an entry from the environment free list, writes an offset-derived byte into the entry and the caller's output, copies source fields into the entry, and returns a non-zero status if the list is empty.",
  "subsystem": "mm",
  "var_renames": {
    "a1": "src_entry",
    "a2": "out_byte",
    "v4": "slot",
    "v5": "slot_stamp",
    "v6": "src_word2"
  },
  "struct_hints": [
    {
      "offset": 4,
      "meaning": "slot word copied from src_entry offset 0"
    },
    {
      "offset": 8,
      "meaning": "slot word copied from src_entry offset 4"
    },
    {
      "offset": 12,
      "meaning": "slot 16-bit word copied from src_entry offset 8"
    },
    {
      "offset": 24,
      "meaning": "slot byte field set from the slot's pool offset and returned via out_byte"
    }
  ]
}
